import { readFile } from "node:fs/promises";
import { checkpoint, restore } from "@tigrisdata/agent-kit";
import { put } from "@tigrisdata/storage";

async function run() {
  // 1. Read and normalize trial_id
  const trialIdRaw = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();

  // S3 bucket names can only contain lowercase letters, numbers, dots, and hyphens.
  // Normalize by converting to lowercase and replacing invalid characters with hyphens.
  const normalize = (name: string) => name.toLowerCase().replace(/[^a-z0-9.-]/g, "-");

  const baseBucket = normalize(`harbor-base-${trialIdRaw}`);
  const forkBucket = normalize(`harbor-restore-${trialIdRaw}`);

  console.log(`Base bucket: ${baseBucket}`);
  console.log(`Fork bucket: ${forkBucket}`);

  // Step A — Take the checkpoint BEFORE writing v3.txt
  console.log("Taking checkpoint...");
  const { data: ckpt, error: ckptErr } = await checkpoint(baseBucket, { name: "before-eval" });
  if (ckptErr) {
    console.error("Checkpoint error:", ckptErr);
    throw ckptErr;
  }
  const snapshotId = ckpt.snapshotId;
  console.log(`Checkpoint taken. Snapshot ID: ${snapshotId}`);

  // Step B — Write data/v3.txt to the base bucket after the checkpoint
  console.log("Uploading data/v3.txt to base bucket...");
  const { error: putErr } = await put("data/v3.txt", "version3", {
    config: { bucket: baseBucket },
    contentType: "text/plain",
  });
  if (putErr) {
    console.error("Put error:", putErr);
    throw putErr;
  }
  console.log("Uploaded data/v3.txt.");

  // Step C — Restore the checkpoint into the fork bucket
  console.log("Restoring checkpoint to fork bucket...");
  const { data: restored, error: restoreErr } = await restore(baseBucket, snapshotId, {
    forkName: forkBucket,
  });
  if (restoreErr) {
    console.error("Restore error:", restoreErr);
    throw restoreErr;
  }
  if (restored.bucket !== forkBucket) {
    throw new Error(`unexpected restored bucket: ${restored.bucket}`);
  }
  console.log(`Restored to ${restored.bucket} successfully.`);
}

run().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});

